# jax.scipy.stats. Expected values are from jax 0.12.0.1 (generated): float32 with x64
# disabled, float64 with x64 enabled (the float64 calls run under jit).

st_expect <- function(got, ..., tol = NULL) {
  want <- list(...)
  if (inherits(got, "jax_value")) got <- list(got)
  testthat::expect_length(got, length(want))
  for (i in seq_along(want)) {
    w <- want[[i]]
    g <- got[[i]]
    testthat::expect_identical(dtype(g), w[[1L]])
    testthat::expect_identical(as.integer(dim(g)), as.integer(w[[2L]]))
    gv <- as.array(g)
    if (length(dim(gv)) > 1L) gv <- aperm(gv)
    gv <- as.vector(gv)
    wv <- w[[3L]]
    rtol <- tol %||% if (w[[1L]] == "float64") 1e-10 else 2e-6
    fin <- is.finite(wv)
    testthat::expect_identical(as.numeric(gv[!fin]), as.numeric(wv[!fin]))
    err <- abs(gv[fin] - wv[fin])
    testthat::expect_true(all(err <= rtol * abs(wv[fin]) + rtol * 1e-3),
                          info = paste("max error", if (length(err)) max(err) else 0))
  }
}

