test_that("scipy_stats_gaussian_kde matches JAX", {
  skip_if_no_backend()
  on.exit(enable_x64(FALSE))
  enable_x64(FALSE)
  k1 <- scipy_stats_gaussian_kde(as_jax(array(c(-0x1p+0, 0, 0x1p-1, 0x1p+1, 0x1.199999999999ap+1)), "float32"))
  st_expect(k1$evaluate(as_jax(array(c(-0x1p-1, 0x1p-1, 0x1.8000000000000p+1)), "float32")), list("float32", c(3L), c(0.196112856, 0.221368641, 0.110652439)))
  st_expect(k1$logpdf(as_jax(array(c(-0x1p-1, 0x1p-1, 0x1.8000000000000p+1)), "float32")), list("float32", c(3L), c(-1.62906492, -1.50792599, -2.20136118)))
  st_expect(k1$covariance, list("float32", c(1L, 1L), c(0.965511739)))
  st_expect(k1$integrate_box_1d(-1, 1), list("float32", integer(0), c(0.413024455)))
  st_expect(k1$integrate_gaussian(0.5, 2), list("float32", integer(0), c(0.182627156)))
  k2 <- scipy_stats_gaussian_kde(as_jax(aperm(array(c(-0x1p+0, 0, 0x1p-1, 0x1p+1, 0x1.199999999999ap+1, 0x1.3333333333333p-2, -0x1.999999999999ap-2, 0x1p+0, 0, 0x1p-1), c(5L, 2L)), c(2, 1)), "float32"), bw_method = "silverman", weights = as_jax(array(c(0x1p+0, 0x1p+1, 0x1p+0, 0x1p+0, 0x1.8000000000000p+1)), "float32"))
  st_expect(k2$pdf(as_jax(aperm(array(c(0, 0x1p+0, 0, -0x1p-1), c(2L, 2L)), c(2, 1)), "float32")), list("float32", c(2L), c(0.0972438157, 0.0786171034)))
  st_expect(k2$inv_cov, list("float32", c(2L, 2L), c(0.928473651, -0.824999154, -0.824999154, 6.4706502)))
  k3 <- scipy_stats_gaussian_kde(as_jax(aperm(array(c(-0x1p+0, 0, 0x1p-1, 0x1p+1, 0x1.199999999999ap+1, 0x1.3333333333333p-2, -0x1.999999999999ap-2, 0x1p+0, 0, 0x1p-1), c(5L, 2L)), c(2, 1)), "float32"), bw_method = 0.7)
  st_expect(k2$integrate_kde(k3), list("float32", integer(0), c(0.0790182054)))
  enable_x64(TRUE)
  k1 <- scipy_stats_gaussian_kde(as_jax(array(c(-0x1p+0, 0, 0x1p-1, 0x1p+1, 0x1.199999999999ap+1)), "float64"))
  st_expect(k1$evaluate(as_jax(array(c(-0x1p-1, 0x1p-1, 0x1.8000000000000p+1)), "float64")), list("float64", c(3L), c(0x1.91a39c5574411p-3, 0x1.c55ceaf61df60p-3, 0x1.c53b77e115336p-4)))
  st_expect(k1$logpdf(as_jax(array(c(-0x1p-1, 0x1p-1, 0x1.8000000000000p+1)), "float64")), list("float64", c(3L), c(-0x1.a10a683f1eb7ep+0, -0x1.82076f49ac4e3p+0, -0x1.19c635a13b0a0p+1)))
  st_expect(k1$covariance, list("float64", c(1L, 1L), c(0x1.ee578a075638fp-1)))
  st_expect(k1$integrate_box_1d(-1, 1), list("float64", integer(0), c(0x1.a6efe34c37577p-2)))
  st_expect(k1$integrate_gaussian(0.5, 2), list("float64", integer(0), c(0x1.76053d181bac9p-3)))
  k2 <- scipy_stats_gaussian_kde(as_jax(aperm(array(c(-0x1p+0, 0, 0x1p-1, 0x1p+1, 0x1.199999999999ap+1, 0x1.3333333333333p-2, -0x1.999999999999ap-2, 0x1p+0, 0, 0x1p-1), c(5L, 2L)), c(2, 1)), "float64"), bw_method = "silverman", weights = as_jax(array(c(0x1p+0, 0x1p+1, 0x1p+0, 0x1p+0, 0x1.8000000000000p+1)), "float64"))
  st_expect(k2$pdf(as_jax(aperm(array(c(0, 0x1p+0, 0, -0x1p-1), c(2L, 2L)), c(2, 1)), "float64")), list("float64", c(2L), c(0x1.8e4f88698cdd0p-4, 0x1.420401833cdbep-4)))
  st_expect(k2$inv_cov, list("float64", c(2L, 2L), c(0x1.db60e7c84fd08p-1, -0x1.a6664c68bc1ffp-1, -0x1.a6664c68bc1ffp-1, 0x1.9e1f2421cd0c5p+2)))
  k3 <- scipy_stats_gaussian_kde(as_jax(aperm(array(c(-0x1p+0, 0, 0x1p-1, 0x1p+1, 0x1.199999999999ap+1, 0x1.3333333333333p-2, -0x1.999999999999ap-2, 0x1p+0, 0, 0x1p-1), c(5L, 2L)), c(2, 1)), "float64"), bw_method = 0.7)
  st_expect(k2$integrate_kde(k3), list("float64", integer(0), c(0x1.43a89ae04d264p-4)))
  expect_identical(k1$d, 1L)
  expect_identical(k2$n, 5L)
  expect_error(k1$integrate_box(0, 1), class = "jax_not_implemented_error")
  enable_x64(FALSE)
  s <- k2$resample(random_key(0L), shape = 7L)
  expect_identical(as.integer(dim(s)), c(2L, 7L))
  leaves <- tree_leaves(k1)
  expect_length(leaves, 5L)
})

test_that("scipy_stats gradients and vmap match JAX", {
  skip_if_no_backend()
  on.exit(enable_x64(FALSE))
  enable_x64(TRUE)
  st_expect(grad(function(x) jnp_sum(scipy_stats_norm_logpdf(x, 0x1p-1, 0x1p+1)))(as_jax(array(c(-0x1p+0, 0x1.3333333333333p-2, 0x1p+1)), "float64")), list("float64", c(3L), c(0x1.8000000000000p-2, 0x1.999999999999ap-5, -0x1.8000000000000p-2)), tol = 1e-9)
