  st_expect(grad(function(x) jnp_sum(scipy_stats_logistic_cdf(x)))(as_jax(array(c(-0x1p+0, 0x1.3333333333333p-2, 0x1p+1)), "float64")), list("float64", c(3L), c(0x1.92a946fa34394p-3, 0x1.f4a68f2f93b7dp-3, 0x1.ae0dc0f990c4cp-4)), tol = 1e-9)
  st_expect(grad(function(x) jnp_sum(scipy_stats_truncnorm_logpdf(x, -0x1p+1, 0x1.8000000000000p+1)))(as_jax(array(c(-0x1p+0, 0x1.3333333333333p-2, 0x1p+1)), "float64")), list("float64", c(3L), c(0x1p+0, -0x1.3333333333333p-2, -0x1p+1)), tol = 1e-9)
  st_expect(grad(function(s) jnp_sum(scipy_stats_norm_logpdf(as_jax(array(c(-0x1p+0, 0x1.3333333333333p-2, 0x1p+1)), "float64"), 0.5, s)))(2), list("float64", integer(0), c(-0x1.dd70a3d70a3d7p-1)), tol = 1e-9)
