  st_expect(vmap(function(r) scipy_stats_multivariate_normal_logpdf(r, jnp_zeros(3L), as_jax(aperm(array(c(0x1p+1, 0x1.3333333333333p-2, 0x1.999999999999ap-4, 0x1.3333333333333p-2, 0x1p+0, -0x1.999999999999ap-3, 0x1.999999999999ap-4, -0x1.999999999999ap-3, 0x1p-1), c(3L, 3L)), c(2, 1)), "float64")))(as_jax(aperm(array(c(0x1.999999999999ap-4, 0x1.999999999999ap-3, 0x1.3333333333333p-2, 0x1p+0, -0x1p+0, 0x1p-1), c(3L, 2L)), c(2, 1)), "float64")), list("float64", c(2L), c(-0x1.698d3167c9c0ap+1, -0x1.d48eef04fd501p+1)))
