test_that("scipy_stats input checks follow JAX", {
  skip_if_no_backend()
  expect_error(scipy_stats_dirichlet_logpdf(c(0.5, 0.5), matrix(1, 2, 2)), class = "jax_value_error")
  expect_error(scipy_stats_dirichlet_logpdf(c(0.2, 0.2, 0.2, 0.4), c(1, 2)), class = "jax_value_error")
  expect_error(scipy_stats_multinomial_logpmf(c(1, 2), 3, c(0.5, 0.5)), class = "jax_value_error")
  expect_error(scipy_stats_mode(c(1, 2), nan_policy = "bad"), class = "jax_value_error")
  expect_error(scipy_stats_mode(c(1, 2), nan_policy = "omit"), class = "jax_not_implemented_error")
  expect_error(scipy_stats_rankdata(c(1, 2), method = "x"), class = "jax_value_error")
  expect_error(scipy_stats_multivariate_normal_logpdf(c(1, 2), c(0, 0), diag(3)), class = "jax_value_error")
  expect_error(scipy_stats_gaussian_kde(1), class = "jax_value_error")
})
